import React from 'react';

import Sunglasses from '@pohodnik/icons/svg/RealWorld/Sunglasses';
import { useNavigate } from 'react-router-dom';

import { getBackpacks } from '@apps/Hiking/@services/equip.service';
import { IBackpack } from '@apps/Hiking/@types/equip.types';
import { addBackpackAsync } from '@apps/Hiking/equip/BackpackEditor/backpackEditorHelper';
import EquipOptionsWidget from '@apps/Hiking/equip/HikingEquip/components/EquipOptionsWidget';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { round } from '@helpers/mathHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohContainer from '@ui-kit/layout/Container';
import PohList from '@ui-kit/List';

const EquipPageBackpacks: React.FC = () => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IBackpack[]>([]);

  const navigate = useNavigate();

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getBackpacks();
      setData(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  return (
    <div>
      <PohBreadcrumbs
        data={[
          { href: '/equip', text: 'Снаряжение' },
          { href: '/equip/backpacks', text: 'Рюкзаки', active: true },
        ]}
      />

      <PohContainer>
        <PageHeader title="Рюкзаки">
          <PohButton
            variant={ButtonVariant.Success}
            size={ButtonSize.Small}
            onClick={async () => {
              const newItem = await addBackpackAsync();
              notificationHelper.success('Добавлено');
              setData((cur) => [...cur, newItem]);
            }}
          >
            Добавить
          </PohButton>
        </PageHeader>
        <p className="mt-n3">
          <small>В этом списке будут все рюкзаки. Именно сами рюкзаки, без содержимого:)</small>
        </p>
        {data.length === 0 && <Empty>Пока тут пусто...</Empty>}
        {data.length > 0 && (
          <PohList
            data={data.map((item) => {
              return {
                key: item.id,
                children: (
                  <div className="d-flex align-items-center flex-nowrap me-n2" style={{ gap: 12 }}>
                    <PohAva src={item.photo} alt={item.name} width={32} icon={<Sunglasses />} />
                    <strong>{item.name}</strong>
                    <EquipOptionsWidget
                      className="ms-auto"
                      weight={round(item.weight)}
                      value={round(+item.value)}
                    />
                  </div>
                ),
                onClick: () => navigate(`/equip/backpacks/${item.id}`),
              };
            })}
          />
        )}
      </PohContainer>
    </div>
  );
};

export default EquipPageBackpacks;
